        try {
            // Validate the URL to ensure it's safe
            if (isValidUrl(userInput)) {
                URL url = new URL(userInput);
                System.out.println("Requesting: " + url.toString());
                // In a real application, this would make an HTTP request
            } else {
                System.out.println("Invalid or unsafe URL.");
            }
        } catch (MalformedURLException e) {
            e.printStackTrace();
        }
    }

    // Simple validation to check if the URL is safe (basic example)
    private static boolean isValidUrl(String url) {
        // Check if the URL starts with a known external domain
        // In a real-world scenario, this would be more complex and use a whitelist
        return url.startsWith("https://") || url.startsWith("http://");
    }
}
